import{t as e}from"./auth.DU1tc4gE.js";e.isAuthenticated()&&(window.location.href=`/`);var t=document.getElementById(`telefono`),n=document.getElementById(`registro-form`),r=document.getElementById(`reg-submit-btn`),i=document.getElementById(`reg-error-alert`),a=document.getElementById(`reg-success-alert`);t&&t.addEventListener(`input`,()=>{t.value=t.value.replace(/\D/g,``).slice(0,10)}),n&&n.addEventListener(`submit`,async t=>{t.preventDefault(),i.style.display=`none`,a.style.display=`none`;let n=document.getElementById(`telefono`),o=n.value.replace(/\D/g,``).slice(0,10);n.value=o;let s=document.getElementById(`nombre`).value.trim(),c=document.getElementById(`email`).value.trim(),l=document.getElementById(`password`).value,u=document.getElementById(`confirmPassword`).value,d=document.getElementById(`direccion`).value.trim();if(o&&!/^\d{10}$/.test(o)){i.textContent=`El teléfono debe contener exactamente 10 digitos y solamente números.`,i.style.display=`block`,n.focus();return}if(!s||!c||!l){i.textContent=`Por favor completa los campos obligatorios (*).`,i.style.display=`block`;return}if(l.length<6){i.textContent=`La contraseña debe contener al menos 6 caracteres.`,i.style.display=`block`;return}if(l!==u){i.textContent=`Las contraseñas no coinciden. Verifícalas.`,i.style.display=`block`;return}r.disabled=!0,r.innerHTML=`<span>Creando cuenta...</span>`;try{a.textContent=`¡Cuenta creada exitosamente! Bienvenido, ${(await e.registro({nombre:s,email:c,password:l,telefono:o,direccion:d})).usuario.nombre}.`,a.style.display=`block`,window.showToast&&window.showToast(`¡Registro exitoso! Iniciando sesión...`,`success`),setTimeout(()=>{window.location.href=`/catalogo`},800)}catch(e){i.textContent=e.message||`Error al registrar la cuenta. Intenta de nuevo.`,i.style.display=`block`,r.disabled=!1,r.innerHTML=`<span>Registrarme y Comenzar</span>`}});